const day=d=>new Date(d.getFullYear(),d.getMonth(),d.getDate());
const validDate=value=>{const d=new Date(value);return Number.isFinite(+d)?d:null;};
export function spacedRecommendations(rows,now=new Date()){
 const today=day(now),result=[];
 for(const signal of new Set(rows.map(r=>r.signal))){const all=rows.filter(r=>r.signal===signal),completed=all.filter(r=>r.resolved&&validDate(r.completedAt||r.date)).sort((a,b)=>+new Date(a.completedAt||a.date)-+new Date(b.completedAt||b.date));
 const sessions=new Map();for(const r of completed){const d=day(new Date(r.completedAt||r.date)),key=+d;if(!sessions.has(key))sessions.set(key,[]);sessions.get(key).push(r);}
 let streak=0;for(const list of sessions.values()){const clean=list.every(r=>!r.errors&&!r.hints&&!r.revealed&&r.points>=85);streak=clean?streak+1:0;}
 const last=completed.at(-1),lastDate=last?day(new Date(last.completedAt||last.date)):null;
 const pending=all.some(r=>!r.resolved&&(r.errors>0||r.hints>0)&&validDate(r.date)&&(!last||+new Date(r.date)>+new Date(last.completedAt||last.date)));
 const interval=streak?[1,3,7,14,30][Math.min(streak-1,4)]:1;
 const due=lastDate?new Date(+lastDate):new Date(+today);if(lastDate)due.setDate(due.getDate()+interval);if(pending)due.setTime(+today);
 const recent=completed.slice(-5),errors=recent.reduce((n,r)=>n+r.errors,0),overdue=Math.max(0,Math.round((+today-+due)/86400000));
 result.push({signal,label:all[0].label,due:due.toISOString(),isDue:due<=today,last:lastDate?.toISOString()||null,daysSince:lastDate?Math.max(0,Math.round((+today-+lastDate)/86400000)):null,interval,streak,priority:overdue*2+errors+(pending?5:0),reason:pending?'Quedó una pregunta con errores o pistas sin resolver.':!last?'Aún no has resuelto una pregunta de esta señal.':streak?'Buen resultado en '+streak+' días de práctica; intervalo de '+interval+' días.':'La última jornada necesitó ayuda o tuvo errores; repaso al día siguiente.'});
 }
 return result.sort((a,b)=>Number(b.isDue)-Number(a.isDue)||b.priority-a.priority||a.due.localeCompare(b.due));
}
export function renderSpacing(host,rows,{ready,start,now=new Date()}){const recommendations=spacedRecommendations(rows,now),due=recommendations.filter(r=>r.isDue);host.replaceChildren();const title=document.createElement('h3');title.textContent='Tu repaso de hoy · '+now.toLocaleDateString('es-CO');host.append(title);const p=document.createElement('p');p.textContent='Según tus errores y los días desde la última práctica resuelta. Intervalos: 1, 3, 7, 14 y 30 días tras jornadas sin ayuda; con errores o pistas, vuelve a 1 día. Repetir muchas veces hoy no alarga el intervalo. Recomendación didáctica local, sin notificaciones automáticas.';host.append(p);const startAll=document.createElement('button');startAll.textContent=due.length?'Practicar prioridades de hoy ('+Math.min(3,due.length)+' señales)':'No tienes repasos vencidos';startAll.disabled=!ready||!due.length;startAll.onclick=()=>start(due.slice(0,3).map(r=>r.signal));host.append(startAll);if(!recommendations.length){const empty=document.createElement('p');empty.textContent='Completa primero ejercicios guiados para crear tu calendario personal.';host.append(empty);}for(const r of recommendations){const card=document.createElement('article');card.className='spacing-card';const h=document.createElement('h4');h.textContent=r.label+' · '+(r.isDue?'Para hoy':'Próximo: '+new Date(r.due).toLocaleDateString('es-CO'));const detail=document.createElement('p');detail.textContent=(r.daysSince===null?'Sin práctica completada.':'Última práctica: hace '+r.daysSince+' días. ')+r.reason;const b=document.createElement('button');b.textContent=r.isDue?'Iniciar reto personalizado':'Practicar antes de tiempo';b.disabled=!ready;b.onclick=()=>start([r.signal]);card.append(h,detail,b);host.append(card);}}
